#include "ScalarConverter.hpp"

# include <cstdlib>
/* string to each type conversion */

# include <cctype> //for isprint()
# include <iostream>

void testScarConverterClass();

int main(int argc, char** argv)
{
	(void)argc;
	(void)argv;



	const bool testEnable = false;
	if (testEnable == true)
	{
		testScarConverterClass();
	}

	if (argc == 2)
	{
		std::cout << "####### USER INPUT : \"" << argv[1] << "\"\n";

		ScalarConverter::convert(argv[1]);

		std::cout << "####################################\n";
	}
	return (0);
}

void testinput(const std::string& input)
{
	static size_t index = 0;

	std::cout << "------------index [" << index++ << "]----------------------------\n";
	std::cout << "testInput: \"" << input << "\"\n";
	ScalarConverter::convert(input);
}

void testScarConverterClass()
{
	std::cout << "================= Ex00 Scalar Converter Tests =============\n" ;

	/* you can try to instantiate the object here*/
	//ScalarConverter a;
	testinput("A"); // 0
	testinput("    A"); // 1
	testinput("A          "); // 2
	testinput("\r\t\t\b\v\fA "); // 3
	testinput("AB"); // 4
	testinput("A B"); // 5
	testinput("A     B      "); // 6
	testinput("   A      "); // 7

	/* 8 */
	testinput("");

	/* 9 */
	testinput("");

	/* 10 */
	testinput("9999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999");

	/* 11 */
	testinput("");

	/* 12 */
	testinput("-");

	/* 13 */
	testinput("0.");

	/* 14 */
	testinput("-0.");

	/* 15 */
	testinput("1.1.1");

	/* 16 */
	testinput("1..1");

	/* 17 */
	testinput("1.1.");

	/* 18 */
	testinput(" \177");

	/* 19 */
	testinput("0x1000.5555555555555f");

	/* 20 */
	testinput("\t");

	/* 21 */
	testinput("\v");

	/* 22 */
	testinput("\n");

	/* 23 */
	testinput("\f");

	/* 24 */
	testinput("\r");

	/* 25 */
	testinput(" ");

	/* 26 */
	testinput("inf");
	/* 27 */
	testinput("+inf");
	/* 28 */
	testinput("++inf");
	/* 29 */
	testinput("-inf");
	/* 30 */
	testinput("--inf");
	/* 31*/
	testinput("inff");
	/* 32 */
	testinput("+inff");
	/* 33 */
	testinput("++inff");
	/* 34 */
	testinput("-inff");
	/* 34 */
	testinput("--inff");
	/* 35 */
	testinput("infff");
	/* 36 */
	testinput("-infff");
	/* 37 */
	testinput("nan");
	/* 38 */
	testinput("nanf");
	/* 39 */
	testinput("nanff");
	/* 40 */
	testinput("nanfff");
	/* 41 */
	testinput("+nan");
	/* 42 */
	testinput("-nan");
	/* 43 */
	testinput("+nanf");
	/* 44 */
	testinput("+nanff");
	/* 45 */
	testinput("++nanf");
	/* 46 */
	testinput("-nanf");
	/* 47 */
	testinput("-nanff");
	/* 48 */
	testinput("-nanfff");
	/* 49 */
	testinput("nannan");
	/* 50 */
	testinput("1213.123");
	/* 51 */
	testinput("67.67");
	std::cout << "================= Ex00 Scalar Converter Tests =============\n" ;
}
